 Xoroshiro128Plus priorStageRng,priorStageGenerator,priorRunRng,priorLoopRng,priorNextStageRng;ulong priorRunSeed;bool ownsRewardRunRng;ItemMask ownedRewardMask;Run rewardRun;TeamComponent rewardFixtureTeam;TeamIndex priorRewardFixtureTeam;readonly List<CharacterMaster> ownedRewardSummons=new List<CharacterMaster>();
