 }
 void RecordRewardSpawn(GameObject obj){r.rewards.spawnEvents++;var master=obj.GetComponent<CharacterMaster>();if(!ownedRewardSummons.Contains(master))ownedRewardSummons.Add(master);if(r.rewards.spawnEvents!=1)return;enemyMasterHost=obj;enemyMaster=master;enemyBody=enemyMaster.GetBody();r.rewards.spawnLevelBeforeStart=enemyBody.level;}
