 void CleanupRewardHosts(){if(r.rewards==null)return;CleanupAutomaticDirector();if(observesRewardSummon){MasterSummon.onServerMasterSummonGlobal-=RewardSummon;observesRewardSummon=false;}if(rewardPlayerMaster)rewardPlayerMaster.OnGoldCollected-=RewardGold;if(rewardFixtureTeam)rewardFixtureTeam.teamIndex=priorRewardFixtureTeam;foreach(var summon in ownedRewardSummons)if(summon&&summon.gameObject!=enemyMasterHost)NetworkServer.Destroy(summon.gameObject);if(rewardExperienceHost)Destroy(rewardExperienceHost);if(rewardDirectorHost)Destroy(rewardDirectorHost);if(rewardPlacementHost)Destroy(rewardPlacementHost);if(rewardCard)Destroy(rewardCard);if(rewardRun){rewardRun.stageRng=priorStageRng;rewardRun.stageRngGenerator=priorStageGenerator;if(ownsRewardRunRng){rewardRun.runRNG=priorRunRng;rewardRun.loopRngGenerator=priorLoopRng;rewardRun.nextStageRng=priorNextStageRng;rewardRun.seed=priorRunSeed;ownsRewardRunRng=false;}if(ownedRewardMask!=null&&rewardRun.expansionLockedItems==ownedRewardMask)rewardRun.expansionLockedItems=null;}if(ownedRewardMask!=null){ItemMask.Return(ownedRewardMask);ownedRewardMask=null;}}
 IEnumerator CleanupEnemyRewards(){
